#include <iostream>

int main() {
    SpscRingBuffer<int, 4> buffer;
    assert(buffer.push(10));
    assert(buffer.push(20));
    int val = 0;
    assert(buffer.pop(val) && val == 10);
    assert(buffer.pop(val) && val == 20);
    assert(!buffer.pop(val));
    std::cout << "C++20 SPSC Ring Buffer Test Passed!\n";
    return 0;
